function Private:ImportBigWigs()
    local ProfileString = "BW2:" -- Paste the BigWigs general-settings export (BW2:) here.

    if ProfileString == "" then return end

    BigWigsAPI.RegisterProfile("ElvUI_Unhalted", ProfileString, "Default", function(Success)
        if not Success then return end
        Private:PrettyPrint("Imported |TInterface\\AddOns\\BigWigs\\Media\\Icons\\minimap_raid.tga:16:16|tBigWigs successfully.")
    end)
end

